<?php

namespace App\Http\Controllers\Auth;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Log;

/**
 * OTP-based email verification.
 *
 * Replaces Laravel's default `MustVerifyEmail` link verification. The 6-digit
 * code is generated by `SendsEmailVerificationOtp::sendEmailVerificationOtpNotification()`
 * (called from AuthController registration flows and the resend route).
 *
 *   GET  /email/verify                       → OTP entry screen
 *   POST /email/verify                       → submit code
 *   POST /email/verification-notification    → regenerate + email new code
 *
 * The 2FA login OTP and the email-verification OTP live on different columns
 * (otp_code vs email_verification_code), so they cannot collide.
 */
class EmailVerificationController extends Controller
{
    /**
     * Show the OTP entry screen. If the user is already verified, send them
     * to the appropriate dashboard via the same redirect-by-role helper used
     * elsewhere in the app.
     */
    public function notice(Request $request)
    {
        $user = $request->user();

        if ($user && method_exists($user, 'hasVerifiedEmail') && $user->hasVerifiedEmail()) {
            return redirect()->intended($this->dashboardFor($user));
        }

        // If the user has no code on file (e.g. an account that pre-dates the
        // OTP migration), generate one proactively.
        if ($user && empty($user->email_verification_code) && !$user->hasVerifiedEmail()) {
            try {
                $user->sendEmailVerificationOtpNotification();
            } catch (\Throwable $e) {
                Log::warning('Proactive email-verification OTP send failed for user ' . $user->id . ': ' . $e->getMessage());
            }
        }

        return view('auth.verify-email-otp');
    }

    /**
     * Validate the submitted 6-digit code.
     */
    public function submit(Request $request)
    {
        $request->validate([
            'code' => 'required|string|digits:6',
        ]);

        $user = $request->user();

        if (!$user) {
            return redirect()->route('login');
        }

        // Reload from DB so we are not looking at a stale cached model.
        $user = $user::find($user->id);

        $result = $user->consumeEmailVerificationOtp($request->code);

        if ($result === 'verified') {
            $request->session()->forget('url.intended');
            return redirect()->intended($this->dashboardFor($user))
                ->with('success', 'Email verified successfully. Welcome to MedRecords.');
        }

        return match ($result) {
            'already'   => redirect()->intended($this->dashboardFor($user)),
            'expired'   => back()->withErrors(['code' => 'This code has expired. Please request a new one.']),
            'no_code'   => back()->withErrors(['code' => 'No verification code on file. Please click "Resend verification code".']),
            'too_many'  => back()->withErrors(['code' => 'Too many incorrect attempts. Please request a new code.']),
            'invalid'   => back()->withErrors(['code' => 'Incorrect code. Please try again.']),
            default     => back()->withErrors(['code' => 'Verification failed. Please try again.']),
        };
    }

    /**
     * Regenerate and email a fresh OTP. Throttled by the route middleware
     * (`throttle:3,1`) to prevent abuse.
     */
    public function resend(Request $request)
    {
        $user = $request->user();

        if (!$user) {
            return redirect()->route('login');
        }

        if (method_exists($user, 'hasVerifiedEmail') && $user->hasVerifiedEmail()) {
            return redirect()->intended($this->dashboardFor($user))
                ->with('success', 'Your email is already verified.');
        }

        try {
            $user->sendEmailVerificationOtpNotification();
        } catch (\Throwable $e) {
            Log::warning('Resend email-verification OTP failed for user ' . $user->id . ': ' . $e->getMessage());
            return back()->withErrors(['code' => 'Could not send a new code right now. Please try again shortly.']);
        }

        return back()->with('success', 'A new 6-digit verification code has been sent to your email.');
    }

    /**
     * Same role-based landing page used by AuthController::redirectByRole.
     */
    private function dashboardFor($user): string
    {
        return match ($user->role ?? '') {
            'patient'                       => route('patient.dashboard'),
            'provider'                      => route('provider.dashboard'),
            'pharmacist'                    => route('pharmacy.dashboard'),
            'facility_admin', 'super_admin' => route('admin.dashboard'),
            default                         => '/',
        };
    }
}
